-- 20261018120001 套用後唯讀檢查：每列都應為 true
SELECT '12 支精靈函式都存在' AS item, (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('wizard_assert_access','wizard_save_room_type','wizard_clean_tier_prices','wizard_save_package','wizard_season_plan','wizard_preview_season_prices','wizard_apply_season_prices','wizard_open_inventory','wizard_precheck_core','wizard_precheck','wizard_submit','wizard_return')) = 12 AS ok
UNION ALL SELECT '全部 SECURITY DEFINER', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('wizard_assert_access','wizard_save_room_type','wizard_clean_tier_prices','wizard_save_package','wizard_season_plan','wizard_preview_season_prices','wizard_apply_season_prices','wizard_open_inventory','wizard_precheck_core','wizard_precheck','wizard_submit','wizard_return') AND p.proname <> 'wizard_clean_tier_prices' AND NOT p.prosecdef)
UNION ALL SELECT '內部函式 authenticated 不能執行', NOT has_function_privilege('authenticated', 'public.wizard_precheck_core(uuid)', 'EXECUTE') AND NOT has_function_privilege('authenticated', 'public.wizard_assert_access(uuid, boolean)', 'EXECUTE') AND NOT has_function_privilege('authenticated', 'public.wizard_season_plan(uuid, date, date, numeric, numeric, boolean)', 'EXECUTE')
UNION ALL SELECT '對外函式 authenticated 可執行、anon 不可', has_function_privilege('authenticated', 'public.wizard_submit(uuid, boolean)', 'EXECUTE') AND NOT has_function_privilege('anon', 'public.wizard_submit(uuid, boolean)', 'EXECUTE')
UNION ALL SELECT 'assert_access 內容含 42501 與 is_active', position('42501' IN replace(pg_get_functiondef('public.wizard_assert_access(uuid, boolean)'::regprocedure), E'\r', '')) > 0 AND position('is_active' IN replace(pg_get_functiondef('public.wizard_assert_access(uuid, boolean)'::regprocedure), E'\r', '')) > 0
UNION ALL SELECT 'save_package_tier_prices 未被修改（不含 wizard）', position('wizard' IN replace(pg_get_functiondef('public.save_package_tier_prices(uuid, jsonb)'::regprocedure), E'\r', '')) = 0;
